-- Apteka Bober DWH: 03_views.sql (11 аналитических витрин и представлений)
USE pteka_bober;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_ai_executive_navigator` AS select `l`.`store_id` AS `ID Аптеки`,`st`.`store_name` AS `Аптека`,`l`.`audit_reason` AS `Тип События`,count(0) AS `Количество за месяц`,(case when (`l`.`audit_reason` = 'PRICE_OBJECTION') then 'Пересмотреть наценку / Внести в LOCAL-маркеры (Слон 5)' when (`l`.`audit_reason` = 'QUEUE_PEAK') then 'КРИТИЧЕСКИЙ ТРАФИК: Выход заведующей на кассу / Пересмотр сменности' when (`l`.`audit_reason` = 'LOW_UX_SKILLS') then 'Слабые продажи: Направить сотрудника на скрипты / Очный тренинг' when (`l`.`audit_reason` = 'DEFECTURA') then 'Мертвая зона: Превентивно расширить Мин-Макс (Слон 3) / Закуп Ривароксабана' when (`l`.`audit_reason` = 'NO_RECIPE') then 'Рецептурный отказ: Норматив РФ соблюден, действия не требуются' else 'Игнорировать: Внекоммерческий шум торгового зала' end) AS `Рекомендация системе`,max(`l`.`log_timestamp`) AS `Последняя фиксация` from (`ai_omni_audit_log` `l` join `stores` `st` on((`st`.`store_id` = `l`.`store_id`))) where (`l`.`log_timestamp` >= (curdate() - interval 30 day)) group by `l`.`store_id`,`st`.`store_name`,`l`.`audit_reason`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_ai_recommendations` AS select `a`.`store_id` AS `store_id`,`a`.`goods_id` AS `goods_id`,`g`.`goods_name` AS `goods_name`,`a`.`rejection_reason` AS `rejection_reason`,count(0) AS `fail_count`,(case when ((`a`.`rejection_reason` = 'PRICE') and (count(0) > 3)) then 'Добавить в LOCAL-маркеры (Слон 5) и снизить цену' when ((`a`.`rejection_reason` = 'OUT_OF_STOCK') and (count(0) > 3)) then 'Увеличить Мин-Макс (Слон 3), товар в дефиците' when (`a`.`rejection_reason` = 'QUEUE') then 'Риск: Нехватка персонала в часы пик (Слон 7)' when (`a`.`rejection_reason` = 'INCOMPETENCE') then 'Обучить персонал: недостаточно знаний по товару' else 'Проанализировать вручную' end) AS `recommendation` from (`ai_demand_log` `a` join `goods` `g` on((`g`.`goods_id` = `a`.`goods_id`))) group by `a`.`store_id`,`a`.`goods_id`,`g`.`goods_name`,`a`.`rejection_reason` having (count(0) > 0);

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_all_valid_declines` AS select `lost_demand_log`.`store_id` AS `store_id`,`lost_demand_log`.`goods_id` AS `goods_id`,`lost_demand_log`.`scan_timestamp` AS `scan_timestamp`,`lost_demand_log`.`lost_qty` AS `lost_qty`,`lost_demand_log`.`defectura_type` AS `defectura_type`,'MANUAL' AS `source` from `lost_demand_log` where (`lost_demand_log`.`validation_status` = 'VALID') union all select `ai_demand_log`.`store_id` AS `store_id`,`ai_demand_log`.`goods_id` AS `goods_id`,`ai_demand_log`.`scan_timestamp` AS `scan_timestamp`,`ai_demand_log`.`lost_qty` AS `lost_qty`,'STORE_FAULT' AS `defectura_type`,'AI_OMNI' AS `source` from `ai_demand_log` where ((`ai_demand_log`.`rejection_reason` = 'OUT_OF_STOCK') and (`ai_demand_log`.`is_converted_to_sale` = 0) and (`ai_demand_log`.`ai_confidence` >= 0.80));

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_cash_register_scan` AS select `g`.`goods_id` AS `goods_id`,`g`.`goods_name` AS `goods_name`,`g`.`is_prescription` AS `is_prescription`,(case when (`g`.`is_prescription` = 1) then 'ВНИМАНИЕ: ТРЕБУЕТСЯ РЕЦЕПТ! ПРОВЕРЬТЕ БЛАНК!' else 'Продажа разрешена (Безрецептурный отпуск)' end) AS `rx_alert_message` from `goods` `g`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_employee_daily_salary` AS with `store_staff_counts` as (select `employees`.`store_id` AS `store_id`,count(0) AS `pharmacists_count` from `employees` where ((`employees`.`is_active` = 1) and (`employees`.`position` = 'PHARMACIST')) group by `employees`.`store_id`) select `s`.`sale_date` AS `Дата смены`,`s`.`store_id` AS `ID Аптеки`,`st`.`store_name` AS `Аптека`,`s`.`employee_id` AS `ID Сотрудника`,concat(`e`.`last_name`,' ',substr(`e`.`first_name`,1,1),'.',(case when (`e`.`middle_name` is not null) then concat(substr(`e`.`middle_name`,1,1),'.') else '' end)) AS `Сотрудник`,(to_days(`s`.`sale_date`) - to_days(`e`.`hire_date`)) AS `Стаж (дней)`,count(distinct `s`.`sale_datetime`) AS `Факт КЧ (чеков)`,round(sum((`s`.`qty` * `s`.`retail_price`)),2) AS `Выручка дня (руб)`,round(sum((`s`.`qty` * (`s`.`retail_price` - `s`.`purchase_price`))),2) AS `Личная маржа (руб)`,round(greatest(0.8,least(1.2,(sum((`s`.`qty` * `s`.`retail_price`)) / nullif((`st`.`daily_to_plan_rub` / coalesce(`ssc`.`pharmacists_count`,2)),0)))),2) AS `Коэф ТО`,round(greatest(0.8,least(1.2,(count(distinct `s`.`sale_datetime`) / nullif((`st`.`daily_checks_plan` / coalesce(`ssc`.`pharmacists_count`,2)),0)))),2) AS `Коэф КЧ`,round((case when ((to_days(`s`.`sale_date`) - to_days(`e`.`hire_date`)) < 90) then greatest(1.0,((greatest(0.8,least(1.2,(sum((`s`.`qty` * `s`.`retail_price`)) / nullif((`st`.`daily_to_plan_rub` / coalesce(`ssc`.`pharmacists_count`,2)),0)))) + greatest(0.8,least(1.2,(count(distinct `s`.`sale_datetime`) / nullif((`st`.`daily_checks_plan` / coalesce(`ssc`.`pharmacists_count`,2)),0))))) / 2)) else ((greatest(0.8,least(1.2,(sum((`s`.`qty` * `s`.`retail_price`)) / nullif((`st`.`daily_to_plan_rub` / coalesce(`ssc`.`pharmacists_count`,2)),0)))) + greatest(0.8,least(1.2,(count(distinct `s`.`sale_datetime`) / nullif((`st`.`daily_checks_plan` / coalesce(`ssc`.`pharmacists_count`,2)),0))))) / 2) end),2) AS `Итоговый коэф оклада`,round((sum((`s`.`qty` * (`s`.`retail_price` - `s`.`purchase_price`))) * 0.12),2) AS `Премия 12% маржи (руб)`,round(((`st`.`norm_per_shift_rub` * (case when ((to_days(`s`.`sale_date`) - to_days(`e`.`hire_date`)) < 90) then greatest(1.0,((greatest(0.8,least(1.2,(sum((`s`.`qty` * `s`.`retail_price`)) / nullif((`st`.`daily_to_plan_rub` / coalesce(`ssc`.`pharmacists_count`,2)),0)))) + greatest(0.8,least(1.2,(count(distinct `s`.`sale_datetime`) / nullif((`st`.`daily_checks_plan` / coalesce(`ssc`.`pharmacists_count`,2)),0))))) / 2)) else ((greatest(0.8,least(1.2,(sum((`s`.`qty` * `s`.`retail_price`)) / nullif((`st`.`daily_to_plan_rub` / coalesce(`ssc`.`pharmacists_count`,2)),0)))) + greatest(0.8,least(1.2,(count(distinct `s`.`sale_datetime`) / nullif((`st`.`daily_checks_plan` / coalesce(`ssc`.`pharmacists_count`,2)),0))))) / 2) end)) + (sum((`s`.`qty` * (`s`.`retail_price` - `s`.`purchase_price`))) * 0.12)),2) AS `Начислено грязными (руб)`,round((((`st`.`norm_per_shift_rub` * (case when ((to_days(`s`.`sale_date`) - to_days(`e`.`hire_date`)) < 90) then greatest(1.0,((greatest(0.8,least(1.2,(sum((`s`.`qty` * `s`.`retail_price`)) / nullif((`st`.`daily_to_plan_rub` / coalesce(`ssc`.`pharmacists_count`,2)),0)))) + greatest(0.8,least(1.2,(count(distinct `s`.`sale_datetime`) / nullif((`st`.`daily_checks_plan` / coalesce(`ssc`.`pharmacists_count`,2)),0))))) / 2)) else ((greatest(0.8,least(1.2,(sum((`s`.`qty` * `s`.`retail_price`)) / nullif((`st`.`daily_to_plan_rub` / coalesce(`ssc`.`pharmacists_count`,2)),0)))) + greatest(0.8,least(1.2,(count(distinct `s`.`sale_datetime`) / nullif((`st`.`daily_checks_plan` / coalesce(`ssc`.`pharmacists_count`,2)),0))))) / 2) end)) + (sum((`s`.`qty` * (`s`.`retail_price` - `s`.`purchase_price`))) * 0.12)) * 0.87),2) AS `ЗП чистыми (руб)` from (((`sales` `s` join `employees` `e` on((`e`.`employee_id` = `s`.`employee_id`))) join `stores` `st` on((`st`.`store_id` = `s`.`store_id`))) left join `store_staff_counts` `ssc` on((`ssc`.`store_id` = `st`.`store_id`))) where ((`e`.`position` = 'PHARMACIST') and ((`e`.`termination_date` is null) or (`s`.`sale_date` <= `e`.`termination_date`))) group by `s`.`sale_date`,`s`.`store_id`,`st`.`store_name`,`s`.`employee_id`,`e`.`last_name`,`e`.`first_name`,`e`.`middle_name`,`e`.`hire_date`,`st`.`daily_to_plan_rub`,`st`.`daily_checks_plan`,`st`.`norm_per_shift_rub`,`ssc`.`pharmacists_count`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_owner_markup_audit` AS select `st`.`store_id` AS `ID Аптеки`,`st`.`store_name` AS `Аптека`,`st`.`segment` AS `Формат`,round(coalesce(`cur`.`to_rub`,0),2) AS `Выручка_тек_мес_руб`,round(coalesce(`cur`.`cogs_rub`,0),2) AS `Себестоимость_закупа_руб`,round((((coalesce(`cur`.`to_rub`,0) / nullif(coalesce(`cur`.`cogs_rub`,0),0)) - 1) * 100),2) AS `Факт_наценка_на_полке_pct`,round(coalesce(`stk`.`shelf_markup_pct`,0),2) AS `Витринная_наценка_остатков_pct`,round(coalesce(`cur`.`front_margin_rub`,0),2) AS `Фронт_маржа_руб`,round(((coalesce(`cur`.`front_margin_rub`,0) / nullif(coalesce(`cur`.`to_rub`,0),0)) * 100),2) AS `Фронт_маржа_pct`,round(coalesce(`cur`.`back_margin_rub`,0),2) AS `Бэк_маржа_ретро_бонусы_руб`,round((coalesce(`cur`.`front_margin_rub`,0) + coalesce(`cur`.`back_margin_rub`,0)),2) AS `Итого_совокупная_маржа_руб`,round((((coalesce(`cur`.`front_margin_rub`,0) + coalesce(`cur`.`back_margin_rub`,0)) / nullif(coalesce(`cur`.`to_rub`,0),0)) * 100),2) AS `Итого_реальная_маржа_pct`,round(((coalesce(`cur`.`back_margin_rub`,0) / nullif((coalesce(`cur`.`front_margin_rub`,0) + coalesce(`cur`.`back_margin_rub`,0)),0)) * 100),1) AS `Доля_бэк_маржи_в_прибыли_pct` from ((`stores` `st` left join (select `s`.`store_id` AS `store_id`,sum((`s`.`qty` * `s`.`retail_price`)) AS `to_rub`,sum((`s`.`qty` * `s`.`purchase_price`)) AS `cogs_rub`,sum((`s`.`qty` * (`s`.`retail_price` - `s`.`purchase_price`))) AS `front_margin_rub`,sum(((`s`.`qty` * `s`.`purchase_price`) * (`g`.`marketing_bonus_pct` / 100))) AS `back_margin_rub` from (`sales` `s` join `goods` `g` on((`g`.`goods_id` = `s`.`goods_id`))) where (`s`.`sale_date` between date_format(curdate(),'%Y-%m-01') and curdate()) group by `s`.`store_id`) `cur` on((`cur`.`store_id` = `st`.`store_id`))) left join (select `goods_batches`.`store_id` AS `store_id`,(((sum((`goods_batches`.`qty` * `goods_batches`.`retail_price`)) / nullif(sum((`goods_batches`.`qty` * `goods_batches`.`purchase_price`)),0)) - 1) * 100) AS `shelf_markup_pct` from `goods_batches` where ((`goods_batches`.`qty` > 0) and (`goods_batches`.`batch_status` = 'ON_SHELF')) group by `goods_batches`.`store_id`) `stk` on((`stk`.`store_id` = `st`.`store_id`))) where (`st`.`is_active` = 1);

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_payroll_ready` AS select `s`.`store_id` AS `store_id`,`s`.`store_name` AS `store_name`,count(`w`.`writeoff_id`) AS `undistributed_writeoffs`,coalesce(sum(`w`.`loss_amount`),0) AS `blocked_amount`,if((count(`w`.`writeoff_id`) = 0),'READY','BLOCKED') AS `payroll_status` from (`stores` `s` left join `expiry_writeoffs` `w` on(((`w`.`store_id` = `s`.`store_id`) and (`w`.`penalty_distributed` = 0)))) group by `s`.`store_id`,`s`.`store_name`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_personal_offers` AS select `b`.`store_id` AS `store_id`,`pr`.`trigger_goods_id` AS `trigger_goods_id`,`pr`.`offer_goods_id` AS `offer_goods_id`,`g_offer`.`goods_name` AS `offer_goods_name`,`g_offer`.`matrix_status` AS `matrix_status`,`pr`.`promo_type` AS `promo_type`,`pr`.`discount_pct` AS `discount_pct`,`b`.`retail_price` AS `price_before`,round((`b`.`retail_price` * (1 - (`pr`.`discount_pct` / 100))),2) AS `price_after`,round((`b`.`retail_price` * (`pr`.`discount_pct` / 100)),2) AS `benefit_rub`,(case when (`g_offer`.`matrix_status` = 'ZNVLP') then `b`.`purchase_price` else round((`b`.`purchase_price` * (1 + (`pr`.`min_markup_guard` / 100))),2) end) AS `dynamic_floor_price` from ((`promo_rules` `pr` join `goods` `g_offer` on((`g_offer`.`goods_id` = `pr`.`offer_goods_id`))) join `goods_batches` `b` on(((`b`.`goods_id` = `pr`.`offer_goods_id`) and (`b`.`qty` > 0)))) where ((`pr`.`is_active` = 1) and (round((`b`.`retail_price` * (1 - (`pr`.`discount_pct` / 100))),2) >= (case when (`g_offer`.`matrix_status` = 'ZNVLP') then `b`.`purchase_price` else round((`b`.`purchase_price` * (1 + (`pr`.`min_markup_guard` / 100))),2) end)));

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_stock_quality` AS select `v_stock_status`.`store_id` AS `store_id`,round(sum(`v_stock_status`.`stock_value_purchase_net`),2) AS `tz_rub_net`,round(((sum((case when (`v_stock_status`.`stock_status` = 'LIQUID') then `v_stock_status`.`stock_value_purchase_net` else 0 end)) / nullif(sum(`v_stock_status`.`stock_value_purchase_net`),0)) * 100),2) AS `liquid_pct`,round(((sum((case when (`v_stock_status`.`stock_status` = 'SURPLUS') then `v_stock_status`.`stock_value_purchase_net` else 0 end)) / nullif(sum(`v_stock_status`.`stock_value_purchase_net`),0)) * 100),2) AS `surplus_pct`,round(((sum((case when (`v_stock_status`.`stock_status` = 'DEAD_STOCK') then `v_stock_status`.`stock_value_purchase_net` else 0 end)) / nullif(sum(`v_stock_status`.`stock_value_purchase_net`),0)) * 100),2) AS `bad_pct`,round(((sum((case when (`v_stock_status`.`stock_status` = 'EXPIRING') then `v_stock_status`.`stock_value_purchase_net` else 0 end)) / nullif(sum(`v_stock_status`.`stock_value_purchase_net`),0)) * 100),2) AS `expiring_pct`,round(((sum((case when (`v_stock_status`.`stock_status` = 'SUSPECT_STAGNATION') then `v_stock_status`.`stock_value_purchase_net` else 0 end)) / nullif(sum(`v_stock_status`.`stock_value_purchase_net`),0)) * 100),2) AS `suspicious_pct`,round(((sum((case when (`v_stock_status`.`stock_status` = 'INCUBATION') then `v_stock_status`.`stock_value_purchase_net` else 0 end)) / nullif(sum(`v_stock_status`.`stock_value_purchase_net`),0)) * 100),2) AS `incubation_pct` from `v_stock_status` group by `v_stock_status`.`store_id`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_stock_status` AS select `b`.`store_id` AS `store_id`,`b`.`goods_id` AS `goods_id`,`g`.`goods_name` AS `goods_name`,`pg`.`group_name` AS `group_name`,sum((case when ((`b`.`batch_status` = 'ON_SHELF') and (`b`.`turnover_anomaly_flag` <> 'CONFIRMED_MISSING')) then `b`.`qty` else 0 end)) AS `qty_on_shelf`,sum((case when (`b`.`batch_status` = 'IN_TRANSIT') then `b`.`qty` else 0 end)) AS `qty_in_transit`,round(sum((case when ((`b`.`batch_status` = 'ON_SHELF') and (`b`.`turnover_anomaly_flag` <> 'CONFIRMED_MISSING')) then (`b`.`qty` * `b`.`purchase_price`) else 0 end)),2) AS `stock_value_purchase`,round(sum((case when ((`b`.`batch_status` = 'ON_SHELF') and (`b`.`turnover_anomaly_flag` <> 'CONFIRMED_MISSING') and (`b`.`purchase_type` <> 'OFFICE_LOAD')) then (`b`.`qty` * `b`.`purchase_price`) else 0 end)),2) AS `stock_value_purchase_net`,round((sum((case when ((`b`.`batch_status` = 'ON_SHELF') and (`b`.`turnover_anomaly_flag` <> 'CONFIRMED_MISSING')) then `b`.`qty` else 0 end)) / nullif((coalesce(`sl`.`sold_30d`,0) / 30.0),0)),1) AS `sku_turnover_days`,(case when (sum((case when ((`b`.`batch_status` = 'ON_SHELF') and (`b`.`turnover_anomaly_flag` <> 'CONFIRMED_MISSING')) then `b`.`qty` else 0 end)) = 0) then 'OUT_OF_STOCK' when (min((case when ((`b`.`batch_status` = 'ON_SHELF') and (`b`.`qty` > 0)) then `b`.`expiry_date` end)) <= (curdate() + interval 90 day)) then 'EXPIRING' when ((max(`b`.`is_returned_dead`) = 1) or ((coalesce(`sl`.`sold_30d`,0) = 0) and ((to_days(curdate()) - to_days(min(`b`.`received_at`))) > `pg`.`shelf_life_days`))) then 'DEAD_STOCK' when ((`mm`.`effective_max` is not null) and (sum((case when ((`b`.`batch_status` = 'ON_SHELF') and (`b`.`turnover_anomaly_flag` <> 'CONFIRMED_MISSING') and (`b`.`purchase_type` <> 'OFFICE_LOAD')) then `b`.`qty` else 0 end)) > `mm`.`effective_max`)) then 'SURPLUS' else 'LIQUID' end) AS `stock_status` from ((((`goods_batches` `b` join `goods` `g` on((`g`.`goods_id` = `b`.`goods_id`))) join `pharm_groups` `pg` on((`pg`.`group_id` = `g`.`group_id`))) left join `min_max` `mm` on(((`mm`.`store_id` = `b`.`store_id`) and (`mm`.`goods_id` = `b`.`goods_id`)))) left join (select `sales`.`store_id` AS `store_id`,`sales`.`goods_id` AS `goods_id`,sum(`sales`.`qty`) AS `sold_30d` from `sales` where (`sales`.`sale_date` >= (curdate() - interval 30 day)) group by `sales`.`store_id`,`sales`.`goods_id`) `sl` on(((`sl`.`store_id` = `b`.`store_id`) and (`sl`.`goods_id` = `b`.`goods_id`)))) group by `b`.`store_id`,`b`.`goods_id`,`g`.`goods_name`,`pg`.`group_name`,`pg`.`shelf_life_days`,`mm`.`effective_max`,`sl`.`sold_30d`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_viability_live` AS select `st`.`store_id` AS `store_id`,curdate() AS `snapshot_date`,coalesce(`past`.`to_past`,0) AS `to_past`,coalesce(`past`.`margin_past`,0) AS `margin_past_rub`,round(((coalesce(`past`.`to_past`,0) / nullif(coalesce(`fc_past`.`plan_to`,`fc`.`plan_to`),0)) * 100),2) AS `plan_exec_past_pct`,coalesce(`cur`.`to_cur`,0) AS `to_current`,coalesce(`cur`.`margin_cur`,0) AS `margin_current_rub`,coalesce(`cur`.`upch`,0) AS `upch`,coalesce(`cur`.`sch`,0) AS `sch`,coalesce(`q`.`tz_rub_net`,0) AS `tz_rub`,coalesce(`q`.`liquid_pct`,0) AS `liquid_share_pct`,coalesce(`q`.`surplus_pct`,0) AS `surplus_share_pct`,coalesce(`q`.`bad_pct`,0) AS `bad_stock_share_pct`,coalesce(`q`.`expiring_pct`,0) AS `expiring_share_pct`,coalesce(`lp`.`lost_margin_sum`,0) AS `lost_profit_rub`,round(if((dayofmonth(curdate()) < 5),coalesce(`fc`.`plan_to`,0),((coalesce(`cur`.`to_cur`,0) / dayofmonth(curdate())) * dayofmonth(last_day(curdate())))),2) AS `to_forecast`,round(if((dayofmonth(curdate()) < 5),100.00,((((coalesce(`cur`.`to_cur`,0) / dayofmonth(curdate())) * dayofmonth(last_day(curdate()))) / nullif(`fc`.`plan_to`,0)) * 100)),2) AS `plan_gap_pct`,(case when ((to_days(curdate()) - to_days(`st`.`opened_date`)) < 30) then 'INCUBATION' when ((coalesce(`lp`.`lost_margin_sum`,0) > (coalesce(`cur`.`to_cur`,0) * 0.15)) and (coalesce(`cur`.`margin_cur`,0) < (coalesce(`fc`.`rent_cost`,0) + coalesce(`fc`.`fot_cost`,0)))) then 'CLOSURE' when ((round(if((dayofmonth(curdate()) < 5),100.00,((((coalesce(`cur`.`to_cur`,0) / dayofmonth(curdate())) * dayofmonth(last_day(curdate()))) / nullif(`fc`.`plan_to`,0)) * 100)),2) > 95) and (coalesce(`q`.`liquid_pct`,0) >= 65)) then 'RENTABLE' else 'RISK_ZONE' end) AS `viability_marker`,(case when ((to_days(curdate()) - to_days(`st`.`opened_date`)) < 30) then 'Стадия раскачки нового объекта' when (coalesce(`lp`.`lost_margin_sum`,0) > (coalesce(`cur`.`to_cur`,0) * 0.15)) then 'Упущенная выгода > 15%' else NULL end) AS `marker_comment` from ((((((`stores` `st` left join `pharmacy_fixed_costs` `fc` on(((`fc`.`store_id` = `st`.`store_id`) and (`fc`.`period` = date_format(curdate(),'%Y-%m-01'))))) left join `pharmacy_fixed_costs` `fc_past` on(((`fc_past`.`store_id` = `st`.`store_id`) and (`fc_past`.`period` = (date_format(curdate(),'%Y-%m-01') - interval 1 month))))) left join (select `sales`.`store_id` AS `store_id`,sum((`sales`.`qty` * `sales`.`retail_price`)) AS `to_past`,sum((`sales`.`qty` * (`sales`.`retail_price` - `sales`.`purchase_price`))) AS `margin_past` from `sales` where (`sales`.`sale_date` between (date_format(curdate(),'%Y-%m-01') - interval 1 month) and (date_format(curdate(),'%Y-%m-01') - interval 1 day)) group by `sales`.`store_id`) `past` on((`past`.`store_id` = `st`.`store_id`))) left join (select `sales`.`store_id` AS `store_id`,sum((`sales`.`qty` * `sales`.`retail_price`)) AS `to_cur`,sum((`sales`.`qty` * (`sales`.`retail_price` - `sales`.`purchase_price`))) AS `margin_cur`,round((sum(`sales`.`qty`) / nullif(count(distinct `sales`.`sale_datetime`),0)),2) AS `upch`,round((sum((`sales`.`qty` * `sales`.`retail_price`)) / nullif(count(distinct `sales`.`sale_datetime`),0)),2) AS `sch` from `sales` where (`sales`.`sale_date` between date_format(curdate(),'%Y-%m-01') and curdate()) group by `sales`.`store_id`) `cur` on((`cur`.`store_id` = `st`.`store_id`))) left join `v_stock_quality` `q` on((`q`.`store_id` = `st`.`store_id`))) left join (select `lost_profit_log`.`store_id` AS `store_id`,sum(`lost_profit_log`.`lost_margin`) AS `lost_margin_sum` from `lost_profit_log` where ((`lost_profit_log`.`calc_date` between date_format(curdate(),'%Y-%m-01') and curdate()) and (`lost_profit_log`.`reason_code` <> 'EXPIRED_WRITEOFF')) group by `lost_profit_log`.`store_id`) `lp` on((`lp`.`store_id` = `st`.`store_id`))) where (`st`.`is_active` = 1);

